package local.lito381.server;
import java.util.*;
public final class SourceNpcMovementPlan {
 static int cases;static void check(boolean b,String why){if(!b)throw new AssertionError(why);cases++;}static void set(Object o,String n,Object v)throws Exception{SourceSignedRecoveryPlan.set(o,n,v);}
 static Object fixture(boolean timed,Object actor,ArenaMapCatalog.Arena arena)throws Exception{
  var e=SourceSignedRecoveryPlan.unsafe().allocateInstance(Class.forName("local.lito381.server."+(timed?"BattleTimeAttackEncounter":"BattleQuestEncounter")));
  if(timed){set(e,"actors",new ArrayList<>(List.of(actor)));set(e,"arena",arena);set(e,"phase",Class.forName("local.lito381.server.BattleTimeAttackEncounter$Phase").getEnumConstants()[3]);set(actor,"activeAi",true);}
  else{var type=Class.forName("local.lito381.server.BattleQuestEncounter$Lane");var ctor=type.getDeclaredConstructor(int.class);ctor.setAccessible(true);var lane=ctor.newInstance(0);((List<Object>)CombatAccess.field(lane,"monsters")).add(actor);var lanes=java.lang.reflect.Array.newInstance(type,1);java.lang.reflect.Array.set(lanes,0,lane);set(e,"lanes",lanes);set(e,"arenas",new ArenaMapCatalog.Arena[]{arena});set(e,"active",true);set(actor,"force",0);set(actor,"roomNumber",1);}return e;
 }
 static Object move(Object e,long id,int x,int y,long now)throws Exception{var m=e.getClass().getDeclaredMethod("moveForAi",long.class,int.class,int.class,long.class);m.setAccessible(true);return m.invoke(e,id,x,y,now);}
 static int[] edge(ArenaMapCatalog.Arena arena){for(int y=arena.minY();y<=arena.maxY();y++)for(int x=arena.minX();x<arena.maxX();x++)if(arena.nativeCanStep(x,y,x+1,y)&&!BattleQuestBoundary.blocksMap(arena.mapId(),1,x,y,x+1,y))return new int[]{x,y,x+1,y};throw new AssertionError("no detached map edge");}
 public static void main(String[]args)throws Exception{
  var oracle=new SourceNpcMovementOracle();int comparisons=0;int[] bounds={Integer.MIN_VALUE,-1,0,1,2,3,10,39,40,41,101,960,65535,1000000,Integer.MAX_VALUE};
  for(boolean timed:new boolean[]{false,true})for(int speed:bounds)for(int attack:bounds)for(boolean ready:new boolean[]{false,true}){var proof=new NativeSourceNpcFactoryType.Stamp("detached",123,"L1Monster",1,0,false,true,false,speed,attack);var actor=SourceNpcTargetFailurePlan.actor(timed,timed?889:888,proof);if(NativeSourceNpcMovement.allowed(ready,actor)!=oracle.allowed(ready,speed))throw new AssertionError("exact Source positive movement gate "+speed+"/"+attack+"/"+ready);comparisons++;}check(comparisons==900,"900 exact Source instance getter/positive-move comparisons, independent of attack speed");
  check(!NativeSourceNpcMovement.allowed(false,new Object()),"original non-ready path returns before actor discovery");check(NativeSourceNpcMovement.allowed(true,new Object())&&NativeSourceNpcMovement.allowed(true,null),"unsupported actor retains complete original permission");
  var arena=ArenaMapCatalog.forMap(554);var step=edge(arena);long now=1000000;int actual=0;
  for(boolean timed:new boolean[]{false,true})for(int speed:new int[]{Integer.MIN_VALUE,-1,0,1,2,960,Integer.MAX_VALUE})for(int attack:new int[]{0,257}){
   var proof=new NativeSourceNpcFactoryType.Stamp("detached",123,"L1Monster",1,0,false,true,false,speed,attack);var actor=SourceNpcTargetFailurePlan.actor(timed,timed?889:888,proof);set(actor,"x",step[0]);set(actor,"y",step[1]);set(actor,"mp",100);set(actor,"nextActionNanos",0L);var e=fixture(timed,actor,arena);var result=move(e,timed?889:888,step[2],step[3],now);boolean allowed=oracle.allowed(true,speed);
   if((result!=null)!=allowed||(int)CombatAccess.field(actor,"x")!=(allowed?step[2]:step[0])||(int)CombatAccess.field(actor,"y")!=(allowed?step[3]:step[1])||(int)CombatAccess.field(actor,"mp")!=100||(long)CombatAccess.field(actor,"nextActionNanos")!=(allowed?now+(long)speed*1000000L:0L))throw new AssertionError("actual original move outcome/position/MP/nextAction "+timed+"/"+speed+"/"+attack);
   if(result!=null&&NativeSourceNpcFactoryMemory.proof(result)!=proof)throw new AssertionError("original accepted snapshot loses birth proof");actual++;
  }check(actual==28,"28 actual original detached moves reject nonpositive Source speed before position/schedule, allow positive speed even with attack0");
  var catalog=BattleAnimationCatalog.get();var sprites=(Map<Integer,Map<Integer,BattleAnimationCatalog.Animation>>)CombatAccess.field(catalog,"sprites");int gfx=sprites.keySet().stream().filter(id->id>0&&catalog.supportsTimedAction(id,0)).mapToInt(Integer::intValue).min().orElseThrow();int inherited=0;
  for(boolean timed:new boolean[]{false,true})for(boolean marked:new boolean[]{false,true}){
   var proof=marked?new NativeSourceNpcFactoryType.Stamp("detached",123,"L1Monster",1,0,false,true,false):null;var actor=SourceNpcTargetFailurePlan.actor(timed,timed?889:888,proof);set(actor,"x",step[0]);set(actor,"y",step[1]);if(timed)set(actor,"gfx",gfx);else{var type=Class.forName("local.lito381.server.BattleQuestEncounter$Template");var ctor=type.getDeclaredConstructor(int.class,int.class,String.class,int.class,int.class,int.class,int.class);ctor.setAccessible(true);set(actor,"template",ctor.newInstance(123,gfx,"detached",1,100,100,1));}var e=fixture(timed,actor,arena);check(move(e,timed?889:888,step[2],step[3],now)!=null,"actual old/null proof retains original movement "+timed+"/"+marked);inherited++;
  }check(inherited==4,"four complete original legacy/unmarked movement paths");
  int guards=0;for(boolean timed:new boolean[]{false,true})for(String status:List.of("nextActionNanos","blindExpiresAtNanos","sleepExpiresAtNanos","paralysisExpiresAtNanos","shockStunExpiresAtNanos","boneBreakExpiresAtNanos","thunderGrabExpiresAtNanos","freezeExpiresAtNanos","earthBindExpiresAtNanos")){
   var proof=new NativeSourceNpcFactoryType.Stamp("detached",123,"L1Monster",1,0,false,true,false,101,0);var actor=SourceNpcTargetFailurePlan.actor(timed,timed?889:888,proof);set(actor,"x",step[0]);set(actor,"y",step[1]);set(actor,status,now+1000000000L);var e=fixture(timed,actor,arena);if(move(e,timed?889:888,step[2],step[3],now)!=null||(int)CombatAccess.field(actor,"x")!=step[0]||(int)CombatAccess.field(actor,"y")!=step[1])throw new AssertionError("original movement guard changed "+timed+"/"+status);guards++;
  }check(guards==18,"18 actual original ready/blind/sleep/paralysis/stun/Bone/Grab/freeze/earth-bind rejections retained");check(NativeSourceNpcMovement.class.getDeclaredFields().length==0,"no mutable movement/escape/heading/actor registry or TLS");
  System.out.println("PASS"+cases+" Source NPC movement original-admission/position/schedule/status/fallback contracts plus900 Source comparisons and50 actual detached original move calls; full escape/AI/IO/Main/SQL/game remains open");
 }
}
